(19, 'pefUnereard', '81719492946', 'cargo888.cn@gmail.com', 'Product Sales', 'Купить шины оптом в ASIANCATALOG', 'Продажа грузовых шин и шин для легковых автомобилей оптом по ценам производителя с НДС! \r\n<a href=https://asiancatalog.ru>Продам шины оптом</a> - ASIANCATALOG \r\nРассрочка платежа, НДС, Маркировка шин \"ЧЗ\", Сертификаты ЕАС \r\nМы заинтересованы в сотрудничестве!', 'new', 'contact-form', '2026-02-14 01:24:37', NULL),
(20, 'Hubertwandy', '88439254832', 'gor.tor.14@mail.ru', 'ICT Support', 'Ваши системы видеонаблюдения', 'Привет всем! \r\n \r\nРешил поделиться своими впечатлениями о бренде <a href=https://www.dahua-ipc.ru>Dahua</a>. Я давно интересуюсь системами видеонаблюдения и вот недавно решил установить себе камеру. Рассматривал разные варианты, но остановился именно на Dahua. \r\n \r\nЧто меня привлекло: \r\n \r\nЦена-качество: Оборудование вполне доступное, при этом работает стабильно и надежно. \r\n \r\nШирокий выбор: Камеры разных форматов, видеорегистраторы, аксессуары — каждый найдет подходящее решение. \r\n \r\nПростота настройки: Даже новичкам разобраться несложно, все интуитивно понятно. \r\n \r\nНовинки и технологии: Постоянно появляются новые модели с улучшенными характеристиками, например, встроенный интеллект для анализа изображений. \r\n \r\nКороче говоря, если ищете качественное оборудование для дома или бизнеса, рекомендую обратить внимание на <a href=https://www.dahua-ipc.ru>Dahua</a>. Уверен, вас порадует результат! \r\n \r\nДелитесь вашим мнением, интересно услышать ваши истории и советы.', 'new', 'contact-form', '2026-02-15 00:59:08', NULL),
(21, 'Forestzerie', '88227454775', 'dukidulence84@gmail.com', 'Other', 'IMPORTANT! YOUR 1.749542 BTC IS MODERN', 'IMPORTANT! THE FRAMEWORK WITHDRAW 1.749542 BTC RIGHT NOW https://hiurls.com/FyOkO \r\n \r\n \r\n \r\n \r\n \r\nBooking ID: n1lh9o2b4u9k5f3ub0jz7w9q2b5r9a0it6pq9d7c8n4w1h9vt6wc6r6l8a4j2u5zj4ch5t0t1j2v0j4rp8me2d8b8t0q5r2sd2jl0s6u7b1w5x3g', 'new', 'contact-form', '2026-02-15 13:12:53', NULL),
(22, 'NSFX Nicky Gope Kundnani SCAM', '86184464376', 'finance@remsanteh-groupe.com.ua', 'ICT Support', 'Regulatory Notices and Blackthorn Finance Ltd NSFX Alchemy Group Xoala Nicky Gope Kundnani', '<a href=\"https://signalsliquidity.blogspot.com/2026/02/signals-and-rebranded-fintech.html\" target=\"_blank\">Regulatory Notices and Corporate Disclosures in Cross-Border Fintech</a> - Review how media narratives evolve around Blackthorn Finance Ltd and NSFX within a regulatory context.', 'new', 'contact-form', '2026-02-17 18:44:23', NULL),
(23, 'Paolo C.', '86737139484', 'giovanni.marinelli1993@outlook.it', 'Quick Website Design', 'Single‑patient Fitness Capsule + modular Rehab Pool', 'Hi, \r\n \r\ntwo tools, one goal: faster, safer rehab in water. \r\n \r\nThe Fitness Capsule is a sealed, single-user hydrotherapy chamber with fresh water for every session – designed for post-op and immunocompromised patients who cannot share a pool but still need full-body water therapy. \r\n \r\nThe modular rehabilitation pool handles everything else: group sessions, gait retraining, balance work, and athletic return-to-running, with a movable floor that lets therapists control load and depth in seconds. \r\n \r\nNo concrete. No construction zone. Just plug clinical hydrotherapy into your existing space and start treating patients in days, not months. \r\n \r\nSee how both systems can fit your workflow: https://lnkz.at/DdN7y', 'new', 'contact-form', '2026-02-18 18:10:11', NULL);
