--

INSERT INTO `projects` (`id`, `title`, `slug`, `short_desc`, `full_desc`, `category`, `project_url`, `status`, `is_featured`, `cover_image`, `tech_stack`, `created_at`, `updated_at`) VALUES
(9, 'Sauna Manager', 'sauna-manager', 'Sauna & Facility Management', 'Sauna Manager is a custom-built management system designed to streamline the day-to-day operations of sauna and wellness facilities. The system centralizes customer sessions, payments, staff activity, and operational records into one secure and easy-to-use platform.', 'ERP', NULL, 'completed', 1, '/uploads/projects/project_20260130_140902_9f06071c.jpg', '[\"PHP\",\"SQL\",\"JS\",\"CSS\",\"BOOTSTRAP\"]', '2026-01-30 16:09:02', NULL),
(10, 'Uganda Aquaculture  Cooperative Union Ltd - Website', 'uacu', 'A movement transforming lives through sustainable fish farming', 'The Uganda Aquaculture Cooperative Union is a national union formed from regional fish farmers\' cooperatives across Uganda, empowering communities through sustainable fish farming practices.\r\n\r\nWith support from the European Union and Government of Uganda, we coordinate 132 cooperatives across six regions, creating opportunities for youth, women, and persons with disabilities.', 'Website', NULL, 'completed', 1, '/uploads/projects/project_20260131_144704_133cd630.jpg', '[\"React\",\"JS\"]', '2026-01-31 09:47:04', NULL),
(11, 'Core ERP System', 'core-erp-system', 'A lightweight, modular ERP core for small teams—featuring safe database access, automation rules, and built-in error/slow-query logging. Designed for reliability on PHP 7+ and easy upgrade to PHP 8.', 'This project is a clean, production-ready ERP foundation built for small and growing teams that need stability, clarity, and control without heavy frameworks. It provides a hardened database layer using prepared statements, consistent query helpers, and defensive error handling to prevent silent failures.\r\n\r\nA flexible automation engine allows rule-based actions driven by payload conditions (numeric and string comparisons), making it easy to trigger workflows such as approvals, alerts, or status changes. Operational visibility is built in through application error logging and slow-query tracking stored directly in the database for easy auditing.\r\n\r\nThe codebase is intentionally lightweight and framework-free, optimized for shared hosting environments running PHP 7+, while remaining forward-compatible with PHP 8. Clear structure, strict typing where supported, and reusable helpers make the system easy to maintain and extend.\r\n\r\nIdeal as a core ERP starter or internal operations platform, this project emphasizes reliability, performance insight, and developer-friendly design.\r\n\r\nTest this product and give us feedback.\r\n\r\nLog In details:\r\nadmin\r\nAdmin123', 'ERP', 'https://www.almatechconsults.com/projects/erp', 'completed', 1, '/uploads/projects/project_20260205_185058_61673001.png', '[\"PHP 8.2+\",\"MySQL/MariaDB\",\"Bootstrap 5\",\"Bootstrap Icons\",\"JavaScript\",\"HTML5\",\"CSS3\",\"JSON\",\"PWA\",\"Apache/Nginx\",\"CSRF Protection\",\"Session Management\",\"Role-Based Access Control (RBAC)\",\"Audit Trail System\",\"API v1\",\"Webhooks\",\"Multi-Factor Authentication (MFA)\",\"CDN (jsDelivr)\",\"Responsive Design\",\"Light/Dark Theme System\",\"Modular Architecture\"]', '2026-02-05 13:50:58', '2026-02-05 14:41:09'),
(12, 'Business Manager Pro', 'business-manager', 'Business Manager V1.2 is a secure, modular ERP & POS system built in Core PHP and MySQL for managing sales, stock, finance, users, and reporting in small to medium businesses.', 'Business Manager V1.2 is a production-ready, role-based ERP and POS system designed for retail shops, hardware stores, and growing SMEs.\r\n\r\nThe system includes:\r\n\r\n• Advanced POS with cart, discounts, and receipt generation\r\n• Stock & inventory management with product tracking\r\n• B2B sales tracking (external sourcing without affecting stock)\r\n• Financial module (expenses, deposits, reports)\r\n• Role-Based Access Control (Admin, Cashier, Manager, etc.)\r\n• Settings manager with grouped configuration\r\n• Audit logs & secure session handling\r\n• Theme customization support\r\n• AJAX-powered operations (no page reload)\r\n• Secure API endpoints with CSRF protection\r\n• Modular file structure for scalability\r\n\r\nThe system is built using secure coding practices compatible with PHP 7.4+ and is optimized for shared hosting environments.\r\n\r\nBusiness Manager is ideal for businesses looking for a lightweight, self-hosted ERP solution without relying on heavy frameworks.', 'ERP, POS, Business', 'https://almatechconsults.com/projects/business_manager_v1.2/', 'completed', 1, '/uploads/projects/project_20260211_124341_3d10d5a7.png', '[\"PHP 7.4\",\"MySQL\",\"Bootstrap 5\",\"JavaScript (ES6)\",\"AJAX\",\"HTML5\",\"CSS3\",\"Apache\",\"jQuery\"]', '2026-02-11 07:43:41', '2026-02-11 07:43:57');

