INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `short_desc`, `bio`, `photo`, `email`, `phone`, `linkedin`, `github`, `website`, `skills`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Ainamaani Allan Mwesigye', 'ainamaani-allan-mwesigye', 'Director', 'Director & Lead Software Engineer driving digital solutions, systems design, and technology strategy.', 'Ainamaani Allan Mwesigye is the Director of Alma Tech Consults and a Lead Software Engineer with a strong passion for building practical digital solutions for businesses and organizations. He leads the company’s technology direction, overseeing the design and development of websites, dashboards, and business systems that are secure, reliable, and easy to manage.\r\n\r\nWith hands-on experience in software development, systems architecture, and ICT infrastructure, Allan combines technical expertise with leadership to ensure projects are delivered with quality and long-term sustainability. He works closely with clients to understand their needs and translate them into efficient digital tools that improve operations, visibility, and growth.\r\n\r\nBeyond development, Allan guides the team in best practices, performance optimization, security awareness, and continuous improvement, ensuring Alma Tech Consults delivers professional and dependable solutions.', '20260131_160735_aab37976d7ab.jpg', NULL, NULL, 'https://www.linkedin.com/in/ainamaani-allan-4b72b9355/', 'https://www.github.com/allanalmatech', '#', 'Leadership, Project Management, PHP, JavaScript, MySQL, Systems Architecture, API Integration, ICT Infrastructure, Linux/cPanel, Web Security, Performance Optimization, UI/UX Oversight, Technical Consulting', 0, 'active', '2026-01-29 13:35:47', '2026-01-31 16:07:35'),
(2, 'David Kikabi', 'david-kikabi', 'Software Engineer', 'Software Engineer focused on building fast, secure web apps with modern technologies.', 'David Kikabi is a Software Engineer at Alma Tech Consults who builds reliable websites, admin dashboards, and business systems. He focuses on clean code, performance, and security, turning ideas into products that are easy to use and easy to maintain.\r\nHe works across the stack, from designing database structures and APIs to implementing user-friendly interfaces and integrating third-party services. David also supports deployments, bug fixes, and continuous improvements to keep systems stable as businesses grow.', '20260131_071325_3cc1a255982d.jpg', NULL, NULL, 'https://www.linkedin.com/davidkikabi', 'https://www.github.com/davidkikabi', 'https://www.da-trend.com', 'React, Java, Flutter, PHP, JavaScript, MySQL, HTML5, CSS3, Bootstrap, REST APIs, Git, Linux/cPanel, SQL Optimization, Security (OWASP Basics), Debugging & Performance', 2, 'active', '2026-01-31 07:13:25', '2026-01-31 08:39:18'),
(3, 'Ampumuza Bronia', 'ampumuza-bronia', 'Chief Executive Officer', 'Chief Executive Officer leading strategy, growth, and innovation at Alma Tech Consults.', 'Ampumuza Bronia is the Chief Executive Officer of Alma Tech Consults, providing strategic leadership and guiding the company’s vision in delivering impactful ICT, digital, and branding solutions to businesses.\r\n\r\nShe oversees operations, partnerships, client relations, and business development, ensuring that Alma Tech Consults remains focused on quality service delivery, innovation, and sustainable growth.\r\n\r\nWith strong expertise in business development, digital transformation, and organizational leadership, Bronia connects technology with real business needs, helping clients improve visibility, efficiency, and performance through modern digital solutions.\r\n\r\nHer leadership fosters a culture of professionalism, creativity, and client-centered service, positioning Alma Tech Consults as a trusted partner for businesses seeking reliable ICT and digital support.', '20260131_073310_143c79cadf6b.jpg', NULL, NULL, 'linkedin.com/', '', '#', 'Leadership, Business Strategy, Digital Transformation, Client Relations, Business Development, Brand Growth, Communication, Organizational Management', 1, 'active', '2026-01-31 07:33:10', '2026-01-31 08:38:00'),
(4, 'Kalemba Estine', 'kalemba-estine', 'Software Engineer', 'Kalemba Estine is a passionate software developer and aspiring AI researcher with experience in system development, data analysis, and applied machine learning.', 'Kalemba Estine is a passionate software developer and aspiring AI researcher with experience in system development, data analysis, and applied machine learning. His work spans web-based systems, academic research projects, and technology-driven problem solving, with a growing focus on artificial intelligence in healthcare and business systems. He is motivated by using technology to create scalable, impactful solutions and continuously expanding his technical and research skills.\r\n\r\nE-mail: einsteinedrias@almatechconsults.com', '20260218_122624_da67c8df9ca8.jpg', NULL, NULL, 'https://www.linkedin.com/', 'https://www.github.com/edrias-einstein', '', 'React, Java, Flutter, PHP, JavaScript, MySQL, HTML5, CSS3, Bootstrap, REST APIs, Git, Linux/cPanel, SQL Optimization, Debugging & Performance', 3, 'active', '2026-02-18 12:26:24', '2026-02-18 12:39:35');

