INSERT INTO `testimonials` (`id`, `client_name`, `client_title`, `company`, `photo`, `message`, `rating`, `is_featured`, `status`, `sort_order`, `project_id`, `show_project_link`, `created_at`, `updated_at`) VALUES
(3, 'Mwesigye N', 'Director', 'Nelux Gardens', '20260130_140322_a9ce5be0.jpeg', 'The management systems implemented for our sauna, CCTV, and general operations have greatly improved efficiency and security. Everything is now well organized, monitored, and easy to manage.', 5, 0, 'published', 0, 9, 1, '2026-01-30 13:03:22', '2026-01-30 13:09:23'),
(4, 'Ampumuza B', 'Director', 'Beta Blend Beverages', '20260131_101015_a6658c96.jpeg', 'The graphics designed for Beta Blend Juice completely transformed our brand. From labels to promotional designs, everything looks clean, fresh, and professional. Our customers now recognize the brand instantly.', 5, 0, 'published', 0, NULL, 0, '2026-01-30 13:04:13', '2026-01-31 10:10:15'),
(5, 'Ssempija R', 'Engineer', 'Private Company', '20260131_104859_bdb38b2d.jpeg', 'AlmaTech delivered exactly what we needed, clean design, solid functionality, and great support throughout the project. Communication was clear, timelines were respected, and the final system works perfectly for our daily operations.', 5, 0, 'published', 3, NULL, 0, '2026-01-31 10:48:59', '2026-01-31 11:14:50'),
(6, 'Lilian', 'Director', 'UACU', '20260131_151507_73add8c0.jpeg', 'A well-built fisheries platform that improves efficiency and visibility. Well done', 5, 0, 'published', 4, 10, 1, '2026-01-31 15:15:07', '2026-01-31 15:15:07');

